// Hitstop 打击停顿（v1.2 C1 暴击档 + v1.4 H1 三档分级：普通 0.2/0.02、暴击 0.05/0.06、HR 0.1/0.05）
// 纯逻辑 + 绘制分离，可 node 测试
const C = require('./config.js');

const EPS = 1e-6; // 浮点计时容差，避免 0.1+0.3 < 0.4 之类的漂移导致定时器不归零

class Juice {
  constructor() {
    this.shakeMag = 0;
    this.shakeLeft = 0;
    this.shakeDir = null;      // v1.4 H3：本帧切割法线（单位化在 shakeOffset 内做）
    this.shakeDirCoef = 0;     // 普通/暴击/连击 0.6；HR 弹开 0.8
    this.flashColor = null;
    this.flashLeft = 0;
    this.flashDur = 0;
    this.timeScale = 1;
    this.slowmoLeft = 0;
    this.slowmoCount = 0; // 本局已用慢动作次数
    this.hitstops = [];   // v1.4 H1：各档 Hitstop 独立计数 [{ scale, left }]
    this.hitstopLeft = 0; // 最长剩余（兼容 v1.2 字段）
    this.hitstopScale = 1;// 激活项中最小 scale（优先级：Hitstop > 慢动作 > 1.0）
    this.darken = 0;      // 慢动作暗角强度 0~1
  }

  _syncHitstop() {
    let maxLeft = 0, minScale = 1;
    for (const h of this.hitstops) {
      if (h.left > maxLeft) maxLeft = h.left;
      if (h.scale < minScale) minScale = h.scale;
    }
    this.hitstopLeft = maxLeft;
    this.hitstopScale = this.hitstops.length ? minScale : 1;
  }

  // 同帧多次触发取最大幅度不叠加（六.2 契约不动）；dir = 方向性震屏法线（H3，可选）
  shake(mag, dur, dir, dirCoef) {
    if (mag > this.shakeMag) {
      this.shakeMag = mag;
      this.shakeDir = dir ? { x: dir.x, y: dir.y } : null;
      this.shakeDirCoef = dirCoef || 0;
    } else if (mag === this.shakeMag && dir && !this.shakeDir) {
      this.shakeDir = { x: dir.x, y: dir.y };
      this.shakeDirCoef = dirCoef || 0;
    }
    if (mag === this.shakeMag && dur > this.shakeLeft) this.shakeLeft = dur;
  }

  trigger(kind, dir) {
    const s = C.SHAKE[kind];
    if (!s) return;
    const coef = (kind === 'hr') ? C.H_SHAKE_DIR.hr : C.H_SHAKE_DIR.normal;
    this.shake(s.mag, s.dur, dir, coef);
  }

  flash(color, dur) {
    this.flashColor = color;
    this.flashDur = dur;
    this.flashLeft = dur;
  }

  // 暴击或单线命中 >=4 触发；一局上限 3 次，第 4 次起只出特效不减速
  trySlowmo(rand) {
    const ok = this.slowmoCount < C.SLOWMO.cap;
    if (ok) {
      this.slowmoCount++;
      this.slowmoLeft = C.SLOWMO.dur;
      this.timeScale = C.SLOWMO.scale;
    }
    return ok;
  }

  // v1.4 H1：Hitstop 分级。kind = 'normal' | 'crit' | 'hr'；无参兼容 v1.2（= 暴击档）
  // 与慢动作叠加取更小值；不消耗慢动作一局 3 次上限，三档 Hitstop 均无自身上限、独立计数
  tryHitstop(kind) {
    const h = C.H_HITSTOP[kind] || C.H_HITSTOP.crit;
    this.hitstops.push({ scale: h.scale, left: h.dur });
    this._syncHitstop();
    this.timeScale = this.hitstopScale;
    return h;
  }

  // dt 为真实时间步长（不受 timeScale 影响）；返回本帧 worldTimeScale
  // timeScale 解析优先级：Hitstop（激活项中最小 scale）> 慢动作(0.3) > 1.0
  update(dt) {
    if (this.shakeLeft > 0) {
      this.shakeLeft -= dt;
      if (this.shakeLeft <= EPS) { this.shakeLeft = 0; this.shakeMag = 0; this.shakeDir = null; }
    }
    if (this.flashLeft > 0) {
      this.flashLeft -= dt;
      if (this.flashLeft <= EPS) { this.flashLeft = 0; this.flashColor = null; }
    }
    if (this.slowmoLeft > 0) {
      this.slowmoLeft -= dt;
      if (this.slowmoLeft <= EPS) { this.slowmoLeft = 0; }
    }
    if (this.hitstops.length) {
      for (let i = this.hitstops.length - 1; i >= 0; i--) {
        this.hitstops[i].left -= dt;
        if (this.hitstops[i].left <= EPS) this.hitstops.splice(i, 1);
      }
      this._syncHitstop();
    }
    // C1/H1：Hitstop 结束后回到慢动作 0.3（若其仍有剩余）；慢动作在 Hitstop 期间到期则直接恢复 1.0
    this.timeScale = this.hitstopLeft > 0 ? this.hitstopScale
      : (this.slowmoLeft > 0 ? C.SLOWMO.scale : 1);
    this.darken = this.slowmoLeft > 0 ? this.slowmoLeft / C.SLOWMO.dur : 0;
    return this.timeScale;
  }

  // 渲染用：当前帧震屏偏移（H3 方向性：沿切割法线偏置，垂直轴保留抖动；幅度/时长规则不变）
  // 垂直轴抖动项乘 0.5 收敛系数：使主向量与法线夹角在随机域内恒 ≤30°（收紧 G H3 QA 判据 4）
  shakeOffset(rand) {
    if (this.shakeMag <= 0) return { x: 0, y: 0 };
    const m = this.shakeMag;
    const rnd = typeof rand === 'function' ? rand : Math.random;
    const dir = this.shakeDir;
    if (!dir) return { x: (rnd() * 2 - 1) * m, y: (rnd() * 2 - 1) * m };
    const len = Math.hypot(dir.x, dir.y) || 1;
    const nx = dir.x / len, ny = dir.y / len;
    const coef = this.shakeDirCoef || 0;
    const along = m * coef * (0.6 + 0.4 * rnd());
    const perp = m * (1 - coef) * rnd() * 0.5;
    const sgn = rnd() < 0.5 ? -1 : 1;
    return { x: nx * along + (-ny) * perp * sgn, y: ny * along + nx * perp * sgn };
  }
}

module.exports = { Juice };

