const { Particles } = require('./particles.js');
const { Juice } = require('./juice.js');
const FX = require('./fx.js');          // v1.2 变更C：缓动 / 跳字 / 暗角
const AV = require('./avatar.js');
const { AvatarCache } = require('./avatar-cache.js'); // v1.4 变更F 3.2：离屏头像缓存

// ===== v1.11 三维立体翻滚：纯函数（无闭包状态 / 无 ctx / 不碰平台 API）=====
// 公式（变更单 A3，原样实现）：
//   mod   = V111_PM_DEPTH · sin(V111_PM_W · age + φ3)
//   roll  = V111_ROLL_AMP  · sin(ωr · age + φr)
//   yaw   = V111_YAW_AMP   · sin(ωy · age + φy + mod)
//   pitch = V111_PITCH_AMP · sin(ωp · age + φp + mod · 0.6)
//   angle = roll ; sx = cos(yaw) ; sy = cos(pitch)（均恒正）
//   sx/sy 再各自钳到 [V111_SX_MIN, 1] / [V111_SY_MIN, 1] —— 钳位只作用于**返回值**，
//   绝不回写 yaw/pitch（写了就破坏相位，下一次采样会跳）。
// 一律用 t.age（绝对时间）推导，禁止逐帧积分 —— 帧长变化不影响结果，QA 可复算。
// 三个不同频率的正弦 + 一条更慢的相位调制 → 屏内 ≈2.3s 每轴往复约一次（"能看出在扭"），
// 但每帧确定、可复现、可测。
// A5：奖励关金人冻结 yaw/pitch（只留 roll）→ sx === sy === 1 恒成立，连切时刀数环/裂痕才可读。
function volumeOf(t) {
  const age = (t && t.age) || 0;
  const mid = (band) => (band[0] + band[1]) / 2;
  const wr = (t && t.v111RollW) || mid(C.V111_ROLL_W);
  const wy = (t && t.v111YawW) || mid(C.V111_YAW_W);
  const wp = (t && t.v111PitchW) || mid(C.V111_PITCH_W);
  const phr = (t && t.v111RollPh) || 0;
  const phy = (t && t.v111YawPh) || 0;
  const php = (t && t.v111PitchPh) || 0;
  const ph3 = (t && t.v111PmPh) || 0;
  const mod = C.V111_PM_DEPTH * Math.sin(C.V111_PM_W * age + ph3);
  const angle = C.V111_ROLL_AMP * Math.sin(wr * age + phr);
  const frozen = !!(t && t.bonusGolden);          // A5：奖励关金人 = 刀数环的可读性优先
  const yaw = frozen ? 0 : C.V111_YAW_AMP * Math.sin(wy * age + phy + mod);
  const pitch = frozen ? 0 : C.V111_PITCH_AMP * Math.sin(wp * age + php + mod * 0.6);
  // 钳位只在出口：yaw/pitch 本身保持原值（相位连续，可复算）
  return {
    angle,
    sx: Math.max(C.V111_SX_MIN, Math.cos(yaw)),
    sy: Math.max(C.V111_SY_MIN, Math.cos(pitch))
  };
}

// spawn 时一次性取定：三轴 ω + 四个初相位（φr/φy/φp/φ3），此后不再随机
function initVolumeParams(rand) {
  const pick = (band) => band[0] + rand() * (band[1] - band[0]);
  return {
    v111RollW: pick(C.V111_ROLL_W),
    v111YawW: pick(C.V111_YAW_W),
    v111PitchW: pick(C.V111_PITCH_W),
    v111RollPh: rand() * Math.PI * 2,
    v111YawPh: rand() * Math.PI * 2,
    v111PitchPh: rand() * Math.PI * 2,
    v111PmPh: rand() * Math.PI * 2
  };
}


