// v1.5 F2：名单行高 100→112、可见 5→4 行（分页补足），给 r=34 头部特写留呼吸空间
const LIST_ROW = { x: 40, startY: 420, rowH: C.V15_F.listRowH, maxVisible: C.V15_F.listMaxVisible, cardH: 96, headR: C.V15_F.listHeadR };
const CARD = { x: 40, w: 670, h: 150, startY: 260, gap: 160 }; // ARMORY
