// 商店购买 —— design-v1.md 4.5 价格契约：0/300/900/1800/3600
const C = require('./config.js');

function weaponById(id) {
  return C.WEAPONS.find(w => w.id === id) || null;
}

function canBuy(ownedIds, coins, id) {
  const w = weaponById(id);
  if (!w) return { ok: false, msg: '无此武器' };
  if (ownedIds.indexOf(id) >= 0) return { ok: false, msg: '已拥有' };
  if (coins < w.price) return { ok: false, msg: '积分不足，还差 ' + (w.price - coins) };
  return { ok: true, msg: '' };
}

// 纯函数：返回新状态，不改入参
function buy(ownedIds, coins, id) {
  const check = canBuy(ownedIds, coins, id);
  if (!check.ok) return { ok: false, msg: check.msg, ownedIds, coins };
  return {
    ok: true, msg: '',
    ownedIds: ownedIds.concat([id]),
    coins: coins - weaponById(id).price
  };
}

// 离下一档未购武器还差多少积分（结算页展示）
function gapToNext(ownedIds, coins) {
  for (const w of C.WEAPONS) {
    if (ownedIds.indexOf(w.id) < 0) return { id: w.id, name: w.name, price: w.price, gap: Math.max(0, w.price - coins) };
  }
  return null; // 满配
}

